SELECT g, main_cat, c FROM (
 SELECT 'g1' g, main_cat, COUNT(*) c FROM items_g1 GROUP BY main_cat
 UNION ALL SELECT 'g2', main_cat, COUNT(*) FROM items_g2 GROUP BY main_cat
 UNION ALL SELECT 'g3', main_cat, COUNT(*) FROM items_g3 GROUP BY main_cat
) ORDER BY g, c DESC LIMIT 40;

SELECT g, main_cat, c FROM (
 SELECT 'g2' g, main_cat, COUNT(*) c FROM items_g2 GROUP BY main_cat
 UNION ALL SELECT 'g3', main_cat, COUNT(*) FROM items_g3 GROUP BY main_cat
) ORDER BY g, c DESC LIMIT 25;

SELECT g, str_nm, COUNT(*) c FROM (
 SELECT 'g1' g, str_nm FROM items_g1
 UNION ALL SELECT 'g2', str_nm FROM items_g2
 UNION ALL SELECT 'g3', str_nm FROM items_g3
) GROUP BY g, str_nm ORDER BY g, c DESC LIMIT 30;

